INSERT INTO repo_subtopics (subtopic_id, name, subtopic_no, description, subtopic_sd_id, review_status, status, version) VALUES ('SUB_COURSE_036_M5_S3', 'state-space', '3', 'state-space refers to a modelling framework that represents system dynamics using state variables and first-order differential or difference equations. In System Modelling and Control, the focus is on the analysis, design, implementation, interpretation, or evaluation of state-space within Mechatronics, particularly where the System Modelling and Control module establishes its technical context.', 'SSD_COURSE_036_M5_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_036_M5_S4', 'feedback', '4', 'feedback: Using measured output information to adjust control action according to the difference between desired and actual behaviour. In System Modelling and Control, the focus is on the analysis, design, implementation, interpretation, or evaluation of feedback within Mechatronics, particularly where the System Modelling and Control module establishes its technical context.', 'SSD_COURSE_036_M5_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_036_M5_S5', 'PID control', '5', 'PID control: Feedback control using proportional, integral, and derivative actions to regulate a process variable based on the control error. In System Modelling and Control, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_036_M5_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_036_M6_S1', 'mechanical-electrical interfaces', '1', 'mechanical-electrical interfaces: Interfaces that connect mechanical components and electrical systems, including sensors, actuators, drives, and signal or power connections. In Mechatronic System Integration, the focus is on the analysis, design, implementation, interpretation, or evaluation of mechanical-electrical interfaces within Mechatronics, particularly where the Mechatronic System Integration module establishes its technical context.', 'SSD_COURSE_036_M6_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_036_M6_S2', 'embedded software', '2', 'embedded software: Software running on a dedicated controller or embedded processor to perform sensing, computation, control, or communication. In Mechatronic System Integration, the focus is on the analysis, design, implementation, interpretation, or evaluation of embedded software within Mechatronics, particularly where the Mechatronic System Integration module establishes its technical context.', 'SSD_COURSE_036_M6_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_036_M6_S3', 'control architecture', '3', 'control architecture refers to the organization of sensors, controllers, actuators, communication paths, and control loops that determines how a mechatronic system is regulated. In Mechatronic System Integration, the focus is on the analysis, design, implementation, interpretation, or evaluation of control architecture within Mechatronics, particularly where the Mechatronic System Integration module establishes its technical context.', 'SSD_COURSE_036_M6_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_036_M6_S4', 'system integration', '4', 'system integration: Combining mechanical, electrical, electronic, control, and software components into a functioning mechatronic system. In Mechatronic System Integration, the focus is on the analysis, design, implementation, interpretation, or evaluation of system integration within Mechatronics, particularly where the Mechatronic System Integration module establishes its technical context.', 'SSD_COURSE_036_M6_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_036_M7_S1', 'verification', '1', 'verification: Process of determining whether a model, design, implementation, or manufactured result satisfies specified requirements or has been constructed correctly. In Testing and Reliability of Mechatronic Systems, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_036_M7_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_036_M7_S2', 'validation', '2', 'validation: Checking that an integrated mechatronic system meets its specified requirements under representative conditions. In Testing and Reliability of Mechatronic Systems, the focus is on the analysis, design, implementation, interpretation, or evaluation of validation within Mechatronics, particularly where the Testing and Reliability of Mechatronic Systems module establishes its technical context.', 'SSD_COURSE_036_M7_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_036_M7_S3', 'fault diagnosis', '3', 'fault diagnosis: Identification, localization, and characterization of faults from observed system behaviour, measurements, alarms, or diagnostic evidence. In Testing and Reliability of Mechatronic Systems, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_036_M7_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_036_M7_S4', 'Engineering calibration', '4', 'Engineering calibration: Establishing the relationship between an instrument or measurement-system indication and values realized by standards under specified conditions, with stated measurement uncertainty and traceability where applicable. In Testing and Reliability of Mechatronic Systems, the focus is on mechatronics → Testing and Reliability of Mechatronic Systems: calibration of sensors, measurement chains, and associated instrumentation; calibration is distinct from adjustment.', 'SSD_COURSE_036_M7_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_036_M7_S5', 'reliability testing', '5', 'reliability testing: Testing performed to characterize whether a mechatronic system or component performs its required function consistently over specified conditions and time. In Testing and Reliability of Mechatronic Systems, the focus is on the analysis, design, implementation, interpretation, or evaluation of reliability testing within Mechatronics, particularly where the Testing and Reliability of Mechatronic Systems module establishes its technical context.', 'SSD_COURSE_036_M7_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_037_M1_S1', 'vapour-compression cycle', '1', 'vapour-compression cycle refers to a refrigeration cycle using evaporation, compression, condensation, and expansion of a working fluid to transfer heat. In Refrigeration Cycles, the focus is on the analysis, design, implementation, interpretation, or evaluation of vapour-compression cycle within Refrigeration and Air Conditioning, particularly where the Refrigeration Cycles module establishes its technical context.', 'SSD_COURSE_037_M1_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_037_M1_S2', 'refrigeration effect', '2', 'refrigeration effect: Heat absorbed by the refrigerant in the evaporator per unit mass of refrigerant circulated. In Refrigeration Cycles, the focus is on the analysis, design, implementation, interpretation, or evaluation of refrigeration effect within Refrigeration and Air Conditioning, particularly where the Refrigeration Cycles module establishes its technical context.', 'SSD_COURSE_037_M1_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_037_M1_S3', 'Coefficient of Performance (COP)', '3', 'COP: Coefficient of Performance, the ratio of useful refrigeration or heating effect to the work or energy input. In Refrigeration Cycles, the focus is on the analysis, design, implementation, interpretation, or evaluation of COP within Refrigeration and Air Conditioning, particularly where the Refrigeration Cycles module establishes its technical context.', 'SSD_COURSE_037_M1_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_037_M1_S4', 'pressure-enthalpy analysis', '4', 'pressure-enthalpy analysis: Use of pressure–enthalpy diagrams or property relations to analyse refrigeration cycles, state changes, work, and heat transfer. In Refrigeration Cycles, the focus is on the analysis, design, implementation, interpretation, or evaluation of pressure-enthalpy analysis within Refrigeration and Air Conditioning, particularly where the Refrigeration Cycles module establishes its technical context.', 'SSD_COURSE_037_M1_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_037_M2_S1', 'refrigerant properties', '1', 'refrigerant properties: Thermodynamic and transport properties used to analyse refrigerant behaviour and select suitable working fluids. In Refrigerants and Environmental Considerations, the focus is on the analysis, design, implementation, interpretation, or evaluation of refrigerant properties within Refrigeration and Air Conditioning, particularly where the Refrigerants and Environmental Considerations module establishes its technical context.', 'SSD_COURSE_037_M2_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_037_M2_S2', 'Refrigerant classification', '2', 'Refrigerant classification: Classification of refrigerants according to thermodynamic, safety, environmental, and application-relevant properties used for refrigerant selection and system design. In Refrigerants and Environmental Considerations, the focus is on curricular scope: Refrigeration and Air Conditioning; The concept is represented at the level of the stated mechanism, properties, constraints, and application criteria.', 'SSD_COURSE_037_M2_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_037_M2_S3', 'safety', '3', 'safety: Protection of people, assets, systems, and the environment from unacceptable risk arising from hazards through prevention, control, mitigation, and protective measures. In Refrigerants and Environmental Considerations, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_037_M2_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_037_M2_S4', 'phase-out and alternatives', '4', 'phase-out and alternatives: Replacement of refrigerants with substances that meet required performance while reducing ozone or climate impacts under applicable rules. In Refrigerants and Environmental Considerations, the focus is on the analysis, design, implementation, interpretation, or evaluation of phase-out and alternatives within Refrigeration and Air Conditioning, particularly where the Refrigerants and Environmental Considerations module establishes its technical context.', 'SSD_COURSE_037_M2_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_037_M3_S1', 'compressors', '1', 'compressors: Machines that raise refrigerant pressure and temperature by supplying mechanical work. In Refrigeration Components, the focus is on the analysis, design, implementation, interpretation, or evaluation of compressors within Refrigeration and Air Conditioning, particularly where the Refrigeration Components module establishes its technical context.', 'SSD_COURSE_037_M3_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_037_M3_S2', 'condensers', '2', 'condensers: Heat exchangers that reject heat from high-pressure refrigerant and condense it to liquid. In Refrigeration Components, the focus is on the analysis, design, implementation, interpretation, or evaluation of condensers within Refrigeration and Air Conditioning, particularly where the Refrigeration Components module establishes its technical context.', 'SSD_COURSE_037_M3_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_037_M3_S3', 'expansion devices', '3', 'expansion devices: Devices that reduce refrigerant pressure and control its flow into the evaporator. In Refrigeration Components, the focus is on the analysis, design, implementation, interpretation, or evaluation of expansion devices within Refrigeration and Air Conditioning, particularly where the Refrigeration Components module establishes its technical context.', 'SSD_COURSE_037_M3_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_037_M3_S4', 'evaporators', '4', 'evaporators: Heat exchangers where refrigerant absorbs heat and evaporates. In Refrigeration Components, the focus is on the analysis, design, implementation, interpretation, or evaluation of evaporators within Refrigeration and Air Conditioning, particularly where the Refrigeration Components module establishes its technical context.', 'SSD_COURSE_037_M3_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_037_M3_S5', 'controls', '5', 'controls: Automatic or manual control functions used to regulate refrigeration and air-conditioning equipment in response to temperature, pressure, flow, or other operating variables. In Refrigeration Components, the focus is on the analysis, design, implementation, interpretation, or evaluation of controls within Refrigeration and Air Conditioning, particularly where the Refrigeration Components module establishes its technical context.', 'SSD_COURSE_037_M3_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_037_M4_S1', 'humidity ratio', '1', 'humidity ratio: Mass of water vapour per unit mass of dry air. In Psychrometrics, the focus is on the analysis, design, implementation, interpretation, or evaluation of humidity ratio within Refrigeration and Air Conditioning, particularly where the Psychrometrics module establishes its technical context.', 'SSD_COURSE_037_M4_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_037_M4_S2', 'relative humidity', '2', 'relative humidity: Ratio of actual water-vapour partial pressure to saturation vapour pressure at the same temperature. In Psychrometrics, the focus is on the analysis, design, implementation, interpretation, or evaluation of relative humidity within Refrigeration and Air Conditioning, particularly where the Psychrometrics module establishes its technical context.', 'SSD_COURSE_037_M4_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_037_M4_S3', 'psychrometric chart', '3', 'psychrometric chart refers to a graphical representation of thermodynamic properties and processes of moist air. In Psychrometrics, the focus is on the analysis, design, implementation, interpretation, or evaluation of psychrometric chart within Refrigeration and Air Conditioning, particularly where the Psychrometrics module establishes its technical context.', 'SSD_COURSE_037_M4_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_037_M4_S4', 'air mixing', '4', 'air mixing: Combining air streams with different temperatures and moisture contents to obtain a resulting mixed-air state. In Psychrometrics, the focus is on the analysis, design, implementation, interpretation, or evaluation of air mixing within Refrigeration and Air Conditioning, particularly where the Psychrometrics module establishes its technical context.', 'SSD_COURSE_037_M4_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_037_M4_S5', 'dew point', '5', 'dew point: Temperature at which air becomes saturated with water vapour when cooled at constant pressure and composition. In Psychrometrics, the focus is on the analysis, design, implementation, interpretation, or evaluation of dew point within Refrigeration and Air Conditioning, particularly where the Psychrometrics module establishes its technical context.', 'SSD_COURSE_037_M4_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_037_M5_S1', 'sensible and latent loads', '1', 'sensible and latent loads: Cooling or heating loads associated respectively with temperature change and moisture addition or removal. In Air-Conditioning Loads, the focus is on the analysis, design, implementation, interpretation, or evaluation of sensible and latent loads within Refrigeration and Air Conditioning, particularly where the Air-Conditioning Loads module establishes its technical context.', 'SSD_COURSE_037_M5_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_037_M5_S2', 'heat gains', '2', 'heat gains: Heat entering an air-conditioned space from occupants, lighting, equipment, solar radiation, conduction, infiltration, and other sources. In Air-Conditioning Loads, the focus is on the analysis, design, implementation, interpretation, or evaluation of heat gains within Refrigeration and Air Conditioning, particularly where the Air-Conditioning Loads module establishes its technical context.', 'SSD_COURSE_037_M5_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_037_M5_S3', 'ventilation', '3', 'ventilation: Intentional supply and removal of air to control indoor air quality and contaminant levels. In Air-Conditioning Loads, the focus is on the analysis, design, implementation, interpretation, or evaluation of ventilation within Refrigeration and Air Conditioning, particularly where the Air-Conditioning Loads module establishes its technical context.', 'SSD_COURSE_037_M5_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_037_M5_S4', 'Air infiltration', '4', 'Air infiltration: Uncontrolled or unintended entry of outdoor air into a conditioned space through leakage paths driven by pressure differences, wind, stack effect, or mechanical-system operation. In Air-Conditioning Loads, the focus is on curricular scope: Refrigeration and Air Conditioning; The concept is represented at the level of the stated mechanism, properties, constraints, and application criteria.', 'SSD_COURSE_037_M5_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_037_M5_S5', 'load calculation', '5', 'load calculation: Estimation of sensible and latent cooling or heating loads used to size air-conditioning equipment and distribution systems. In Air-Conditioning Loads, the focus is on the analysis, design, implementation, interpretation, or evaluation of load calculation within Refrigeration and Air Conditioning, particularly where the Air-Conditioning Loads module establishes its technical context.', 'SSD_COURSE_037_M5_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_037_M6_S1', 'all-air systems', '1', 'all-air systems: HVAC systems in which conditioned air is used to provide both heating/cooling and ventilation. In Air-Conditioning Systems, the focus is on the analysis, design, implementation, interpretation, or evaluation of all-air systems within Refrigeration and Air Conditioning, particularly where the Air-Conditioning Systems module establishes its technical context.', 'SSD_COURSE_037_M6_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_037_M6_S2', 'chilled-water systems', '2', 'chilled-water systems: HVAC systems that circulate chilled water to coils that condition air or spaces. In Air-Conditioning Systems, the focus is on the analysis, design, implementation, interpretation, or evaluation of chilled-water systems within Refrigeration and Air Conditioning, particularly where the Air-Conditioning Systems module establishes its technical context.', 'SSD_COURSE_037_M6_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_037_M6_S3', 'variable air volume', '3', 'variable air volume refers to an HVAC control approach that varies supply-air flow to meet changing zone loads. In Air-Conditioning Systems, the focus is on the analysis, design, implementation, interpretation, or evaluation of variable air volume within Refrigeration and Air Conditioning, particularly where the Air-Conditioning Systems module establishes its technical context.', 'SSD_COURSE_037_M6_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_037_M6_S4', 'equipment selection', '4', 'equipment selection: Selection and sizing of refrigeration or air-conditioning equipment to meet required capacity, efficiency, operating conditions, and system constraints. In Air-Conditioning Systems, the focus is on the analysis, design, implementation, interpretation, or evaluation of equipment selection within Refrigeration and Air Conditioning, particularly where the Air-Conditioning Systems module establishes its technical context.', 'SSD_COURSE_037_M6_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_037_M7_S1', 'Coefficient of Performance / Energy Efficiency Ratio (COP/EER)', '1', 'COP/EER: Performance measures relating useful cooling or heating output to energy input under specified conditions. In System Performance and Diagnostics, the focus is on the analysis, design, implementation, interpretation, or evaluation of COP/EER within Refrigeration and Air Conditioning, particularly where the System Performance and Diagnostics module establishes its technical context.', 'SSD_COURSE_037_M7_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_037_M7_S2', 'part-load performance', '2', 'part-load performance: System efficiency and capacity behaviour when operating below full design load. In System Performance and Diagnostics, the focus is on the analysis, design, implementation, interpretation, or evaluation of part-load performance within Refrigeration and Air Conditioning, particularly where the System Performance and Diagnostics module establishes its technical context.', 'SSD_COURSE_037_M7_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_037_M7_S3', 'commissioning', '3', 'commissioning: Systematic verification that HVAC equipment and controls are installed, configured, and operating as intended. In System Performance and Diagnostics, the focus is on the analysis, design, implementation, interpretation, or evaluation of commissioning within Refrigeration and Air Conditioning, particularly where the System Performance and Diagnostics module establishes its technical context.', 'SSD_COURSE_037_M7_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_037_M7_S4', 'fault diagnosis', '4', 'fault diagnosis: Identification, localization, and characterization of faults from observed system behaviour, measurements, alarms, or diagnostic evidence. In System Performance and Diagnostics, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_037_M7_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_037_M7_S5', 'maintenance', '5', 'maintenance: Inspection, servicing, cleaning, adjustment, and repair used to maintain HVAC performance and reliability. In System Performance and Diagnostics, the focus is on the analysis, design, implementation, interpretation, or evaluation of maintenance within Refrigeration and Air Conditioning, particularly where the System Performance and Diagnostics module establishes its technical context.', 'SSD_COURSE_037_M7_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_038_M1_S1', 'Otto cycle', '1', 'Otto cycle refers to an ideal thermodynamic cycle used to represent spark-ignition engine operation. In Engine Cycles and Architecture, the focus is on the analysis, design, implementation, interpretation, or evaluation of Otto cycle within Internal Combustion Engines, particularly where the Engine Cycles and Architecture module establishes its technical context.', 'SSD_COURSE_038_M1_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_038_M1_S2', 'Diesel cycle', '2', 'Diesel cycle refers to an ideal thermodynamic cycle used to represent compression-ignition engine operation with heat addition at approximately constant pressure. In Engine Cycles and Architecture, the focus is on the analysis, design, implementation, interpretation, or evaluation of Diesel cycle within Internal Combustion Engines, particularly where the Engine Cycles and Architecture module establishes its technical context.', 'SSD_COURSE_038_M1_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_038_M1_S3', 'dual cycle', '3', 'dual cycle refers to an ideal engine cycle in which heat addition is represented partly at constant volume and partly at constant pressure. In Engine Cycles and Architecture, the focus is on the analysis, design, implementation, interpretation, or evaluation of dual cycle within Internal Combustion Engines, particularly where the Engine Cycles and Architecture module establishes its technical context.', 'SSD_COURSE_038_M1_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_038_M1_S4', 'two-stroke/four-stroke', '4', 'two-stroke/four-stroke: Engine operating cycles distinguished by whether the sequence of intake, compression, power, and exhaust occurs over two or four piston strokes. In Engine Cycles and Architecture, the focus is on the analysis, design, implementation, interpretation, or evaluation of two-stroke/four-stroke within Internal Combustion Engines, particularly where the Engine Cycles and Architecture module establishes its technical context.', 'SSD_COURSE_038_M1_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_038_M1_S5', 'engine configurations', '5', 'engine configurations: Arrangements of engine cylinders, valve trains, crank mechanisms, induction systems, and other major components that determine engine architecture. In Engine Cycles and Architecture, the focus is on the analysis, design, implementation, interpretation, or evaluation of engine configurations within Internal Combustion Engines, particularly where the Engine Cycles and Architecture module establishes its technical context.', 'SSD_COURSE_038_M1_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_038_M2_S1', 'cylinder', '1', 'cylinder refers to the engine chamber in which the piston moves and combustion or gas exchange occurs. In Engine Components and Mechanics, the focus is on the analysis, design, implementation, interpretation, or evaluation of cylinder within Internal Combustion Engines, particularly where the Engine Components and Mechanics module establishes its technical context.', 'SSD_COURSE_038_M2_S1', 'Semantically_Audited', 'Active', '4.0') ON CONFLICT DO NOTHING;